CREATE TABLE inventory (item_name TEXT, cost INTEGER);
INSERT INTO inventory VALUES ('Mana Crystal', 100), ('Dragon Scale Armor', 500), ('Apple', 5);
-- Find expensive inventory items:
SELECT * FROM inventory WHERE cost > 50;

